"""Order fulfillment candidate API."""

from __future__ import annotations

import json
import math
import sqlite3
import time
from typing import Any, Callable, Iterable

SCHEMA_VERSION = 1

ORDER_STATUSES = ("pending", "paid", "shipped", "cancelled")

ORDER_ERROR_CODES = frozenset(
    {
        "INVALID_INPUT",
        "INVALID_DEPENDENCY",
        "NOT_FOUND",
        "INSUFFICIENT_STOCK",
        "IDEMPOTENCY_CONFLICT",
        "PAYMENT_CONFLICT",
        "AMOUNT_MISMATCH",
        "INVALID_STATE",
        "ID_COLLISION",
        "SCHEMA_MISMATCH",
        "STORAGE_ERROR",
    }
)


class OrderError(Exception):
    """Stable order-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code: str = code
        self.message: str = message
        self.details: dict[str, object] = details if details is not None else {}

    def __str__(self) -> str:
        return self.message

    def __repr__(self) -> str:
        return f"OrderError({self.code!r}, {self.message!r})"

    def to_envelope(self) -> dict[str, Any]:
        return {"code": self.code, "message": self.message, "details": self.details}


def _is_nonempty_str(value: Any) -> bool:
    return isinstance(value, str) and value != "" and not value.isspace()


def _is_nonneg_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _is_pos_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def _is_finite_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _validate_sku(sku: Any) -> None:
    if not _is_nonempty_str(sku):
        raise OrderError("INVALID_INPUT", "sku must be a non-empty non-whitespace string", {"field": "sku"})


def _validate_idempotency_key(key: Any) -> None:
    if not _is_nonempty_str(key):
        raise OrderError(
            "INVALID_INPUT",
            "idempotency_key must be a non-empty non-whitespace string",
            {"field": "idempotency_key"},
        )


def _validate_order_id(order_id: Any) -> None:
    if not _is_nonempty_str(order_id):
        raise OrderError(
            "INVALID_INPUT",
            "order_id must be a non-empty non-whitespace string",
            {"field": "order_id"},
        )


def _validate_payment_id(payment_id: Any) -> None:
    if not _is_nonempty_str(payment_id):
        raise OrderError(
            "INVALID_INPUT",
            "payment_id must be a non-empty non-whitespace string",
            {"field": "payment_id"},
        )


def _validate_items(items: Any) -> list[dict[str, Any]]:
    if not isinstance(items, list) or len(items) == 0:
        raise OrderError("INVALID_INPUT", "items must be a non-empty list", {"field": "items"})
    seen_skus: set[str] = set()
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise OrderError("INVALID_INPUT", "each item must be an object", {"field": f"items[{idx}]"})
        keys = set(item.keys())
        required = {"sku", "quantity", "unit_price_cents"}
        if keys != required:
            extra = keys - required
            missing = required - keys
            detail = {"field": f"items[{idx}]"}
            if extra:
                detail["extra_fields"] = sorted(extra)
            if missing:
                detail["missing_fields"] = sorted(missing)
            raise OrderError("INVALID_INPUT", "item must contain exactly sku, quantity, unit_price_cents", detail)
        sku = item["sku"]
        if not _is_nonempty_str(sku):
            raise OrderError("INVALID_INPUT", "item sku must be a non-empty non-whitespace string", {"field": f"items[{idx}].sku"})
        if sku in seen_skus:
            raise OrderError("INVALID_INPUT", "duplicate SKU in items", {"sku": sku})
        seen_skus.add(sku)
        qty = item["quantity"]
        if not _is_pos_int(qty):
            raise OrderError(
                "INVALID_INPUT",
                "item quantity must be a positive integer",
                {"field": f"items[{idx}].quantity"},
            )
        price = item["unit_price_cents"]
        if not _is_nonneg_int(price):
            raise OrderError(
                "INVALID_INPUT",
                "item unit_price_cents must be a non-negative integer",
                {"field": f"items[{idx}].unit_price_cents"},
            )
    return items


def _canonical_items(items: list[dict[str, Any]]) -> list[tuple[str, int, int]]:
    return sorted((it["sku"], it["quantity"], it["unit_price_cents"]) for it in items)


def _items_signature(items: list[dict[str, Any]]) -> str:
    return json.dumps(_canonical_items(items), separators=(",", ":"), sort_keys=True)


def _row_to_order(row: sqlite3.Row) -> dict[str, Any]:
    return {
        "order_id": row["order_id"],
        "idempotency_key": row["idempotency_key"],
        "status": row["status"],
        "total_cents": row["total_cents"],
        "payment_id": row["payment_id"],
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }


class OrderService:
    """SQLite-backed order service."""

    def __init__(self, db_path, *, clock: Callable[[], float], id_factory: Callable[[], str]):
        if not callable(clock):
            raise OrderError("INVALID_INPUT", "clock must be callable", {"field": "clock"})
        if not callable(id_factory):
            raise OrderError("INVALID_INPUT", "id_factory must be callable", {"field": "id_factory"})
        self._db_path = db_path
        self._clock = clock
        self._id_factory = id_factory
        self._conn = sqlite3.connect(db_path)
        self._conn.row_factory = sqlite3.Row
        self._conn.execute("PRAGMA foreign_keys = ON")
        self._conn.execute("PRAGMA journal_mode = WAL")
        self._init_schema()

    def _init_schema(self) -> None:
        cur = self._conn.cursor()
        cur.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='meta'"
        )
        if cur.fetchone() is None:
            self._conn.execute(
                "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)"
            )
            self._conn.execute(
                "CREATE TABLE stock (sku TEXT PRIMARY KEY, available INTEGER NOT NULL CHECK(available >= 0))"
            )
            self._conn.execute(
                "CREATE TABLE orders ("
                "order_id TEXT PRIMARY KEY, "
                "idempotency_key TEXT NOT NULL UNIQUE, "
                "canonical_items TEXT NOT NULL, "
                "status TEXT NOT NULL CHECK(status IN ('pending','paid','shipped','cancelled')), "
                "total_cents INTEGER NOT NULL, "
                "payment_id TEXT, "
                "created_at REAL NOT NULL, "
                "updated_at REAL NOT NULL)"
            )
            self._conn.execute(
                "CREATE TABLE order_items ("
                "order_id TEXT NOT NULL, "
                "sku TEXT NOT NULL, "
                "quantity INTEGER NOT NULL, "
                "unit_price_cents INTEGER NOT NULL, "
                "PRIMARY KEY (order_id, sku), "
                "FOREIGN KEY (order_id) REFERENCES orders(order_id))"
            )
            self._conn.execute(
                "INSERT INTO meta(key, value) VALUES('schema_version', ?)",
                (str(SCHEMA_VERSION),),
            )
            self._conn.commit()
            return
        # Validate existing schema
        cur.execute("SELECT value FROM meta WHERE key='schema_version'")
        row = cur.fetchone()
        if row is None:
            raise OrderError("SCHEMA_MISMATCH", "missing schema_version in meta")
        try:
            ver = int(row["value"])
        except (TypeError, ValueError):
            raise OrderError("SCHEMA_MISMATCH", "invalid schema_version value")
        if ver != SCHEMA_VERSION:
            raise OrderError("SCHEMA_MISMATCH", f"schema version mismatch: expected {SCHEMA_VERSION}, got {ver}")
        # Verify required tables
        required_tables = {"stock", "orders", "order_items"}
        cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
        existing_tables = {r["name"] for r in cur.fetchall()} - {"meta"}
        if existing_tables != required_tables:
            raise OrderError(
                "SCHEMA_MISMATCH",
                "incompatible schema tables",
                {"expected": sorted(required_tables), "actual": sorted(existing_tables)},
            )
        # Verify order_items structure
        cur.execute("PRAGMA table_info(order_items)")
        order_items_cols = {r["name"] for r in cur.fetchall()}
        if order_items_cols != {"order_id", "sku", "quantity", "unit_price_cents"}:
            raise OrderError("SCHEMA_MISMATCH", "incompatible order_items columns")
        cur.execute("PRAGMA table_info(orders)")
        orders_cols = {r["name"] for r in cur.fetchall()}
        required_orders = {"order_id", "idempotency_key", "canonical_items", "status", "total_cents", "payment_id", "created_at", "updated_at"}
        if not required_orders <= orders_cols:
            raise OrderError("SCHEMA_MISMATCH", "incompatible orders columns")

    def close(self) -> None:
        try:
            self._conn.close()
        except Exception:
            pass

    def _get_items_for_order(self, order_id: str) -> list[dict[str, Any]]:
        cur = self._conn.execute(
            "SELECT sku, quantity, unit_price_cents FROM order_items WHERE order_id=? ORDER BY sku",
            (order_id,),
        )
        return [{"sku": r["sku"], "quantity": r["quantity"], "unit_price_cents": r["unit_price_cents"]} for r in cur.fetchall()]

    def _order_to_dict(self, order_id: str, *, include_items: bool = True) -> dict[str, Any]:
        row = self._conn.execute(
            "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
            "FROM orders WHERE order_id=?",
            (order_id,),
        ).fetchone()
        if row is None:
            raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})
        result = _row_to_order(row)
        if include_items:
            result["items"] = self._get_items_for_order(order_id)
        else:
            result["items"] = []
        return result

    def _get_clock(self) -> float:
        try:
            value = self._clock()
        except Exception as exc:
            raise OrderError("INVALID_DEPENDENCY", f"clock dependency failure: {exc}") from exc
        if not _is_finite_number(value):
            raise OrderError("INVALID_DEPENDENCY", "clock must return a finite number")
        return float(value)

    def _gen_order_id(self, existing_ids: set[str]) -> str:
        for attempt in range(3):
            try:
                candidate = self._id_factory()
            except Exception as exc:
                raise OrderError("INVALID_DEPENDENCY", f"id_factory failure: {exc}") from exc
            if not _is_nonempty_str(candidate):
                raise OrderError(
                    "INVALID_DEPENDENCY",
                    "id_factory must return a non-empty non-whitespace string",
                )
            if candidate not in existing_ids:
                return candidate
        raise OrderError("ID_COLLISION", "failed to generate a unique order ID after 3 attempts")

    def set_stock(self, sku: str, quantity: int) -> dict[str, Any]:
        _validate_sku(sku)
        if not _is_nonneg_int(quantity):
            raise OrderError(
                "INVALID_INPUT",
                "quantity must be a non-negative integer",
                {"field": "quantity"},
            )
        try:
            self._conn.execute(
                "INSERT INTO stock(sku, available) VALUES(?, ?) "
                "ON CONFLICT(sku) DO UPDATE SET available=excluded.available",
                (sku, quantity),
            )
            self._conn.commit()
        except Exception as exc:
            raise OrderError("STORAGE_ERROR", f"failed to set stock: {exc}") from exc
        return {"sku": sku, "available": quantity}

    def create_order(self, idempotency_key: str, items: list[dict[str, Any]]) -> dict[str, Any]:
        _validate_idempotency_key(idempotency_key)
        _validate_items(items)
        canonical = _items_signature(items)
        triples = _canonical_items(items)
        total_cents = sum(qty * price for _, qty, price in triples)

        try:
            # Check idempotency first (read-only, no clock needed)
            row = self._conn.execute(
                "SELECT order_id, canonical_items FROM orders WHERE idempotency_key=?",
                (idempotency_key,),
            ).fetchone()
            if row is not None:
                if row["canonical_items"] != canonical:
                    raise OrderError(
                        "IDEMPOTENCY_CONFLICT",
                        "idempotency key already used with different items",
                        {"idempotency_key": idempotency_key},
                    )
                return self._order_to_dict(row["order_id"])

            # Now we need to create - use a write transaction with IMMEDIATE to acquire lock early
            # Use a fresh connection approach: we do the whole thing in one write transaction
            # First check stock
            skus_needed = [t[0] for t in triples]
            placeholders = ",".join("?" * len(skus_needed))
            stock_rows = self._conn.execute(
                f"SELECT sku, available FROM stock WHERE sku IN ({placeholders})",
                skus_needed,
            ).fetchall()
            stock_map = {r["sku"]: r["available"] for r in stock_rows}
            for sku, qty, _ in triples:
                avail = stock_map.get(sku, 0)
                if avail < qty:
                    raise OrderError(
                        "INSUFFICIENT_STOCK",
                        f"insufficient stock for sku={sku}: need {qty}, have {avail}",
                        {"sku": sku, "needed": qty, "available": avail},
                    )

            now = self._get_clock()

            # Get existing order IDs to check uniqueness
            existing_ids = {r["order_id"] for r in self._conn.execute("SELECT order_id FROM orders").fetchall()}
            order_id = self._gen_order_id(existing_ids)

            try:
                self._conn.execute("BEGIN IMMEDIATE")
                # Re-check idempotency within transaction (double-check after lock)
                row = self._conn.execute(
                    "SELECT order_id, canonical_items FROM orders WHERE idempotency_key=?",
                    (idempotency_key,),
                ).fetchone()
                if row is not None:
                    if row["canonical_items"] != canonical:
                        raise OrderError(
                            "IDEMPOTENCY_CONFLICT",
                            "idempotency key already used with different items",
                            {"idempotency_key": idempotency_key},
                        )
                    return self._order_to_dict(row["order_id"])

                # Re-check stock within transaction
                stock_rows = self._conn.execute(
                    f"SELECT sku, available FROM stock WHERE sku IN ({placeholders})",
                    skus_needed,
                ).fetchall()
                stock_map = {r["sku"]: r["available"] for r in stock_rows}
                for sku, qty, _ in triples:
                    avail = stock_map.get(sku, 0)
                    if avail < qty:
                        raise OrderError(
                            "INSUFFICIENT_STOCK",
                            f"insufficient stock for sku={sku}: need {qty}, have {avail}",
                            {"sku": sku, "needed": qty, "available": avail},
                        )

                # Decrement stock
                for sku, qty, _ in triples:
                    self._conn.execute(
                        "UPDATE stock SET available = available - ? WHERE sku=?",
                        (qty, sku),
                    )

                # Insert order
                self._conn.execute(
                    "INSERT INTO orders(order_id, idempotency_key, canonical_items, status, total_cents, payment_id, created_at, updated_at) "
                    "VALUES(?, ?, ?, 'pending', ?, NULL, ?, ?)",
                    (order_id, idempotency_key, canonical, total_cents, now, now),
                )
                # Insert order items
                for sku, qty, price in triples:
                    self._conn.execute(
                        "INSERT INTO order_items(order_id, sku, quantity, unit_price_cents) VALUES(?, ?, ?, ?)",
                        (order_id, sku, qty, price),
                    )
                self._conn.commit()
            except OrderError:
                self._conn.rollback()
                raise
            except Exception as exc:
                self._conn.rollback()
                raise OrderError("STORAGE_ERROR", f"failed to create order: {exc}") from exc

            return self._order_to_dict(order_id)
        except OrderError:
            raise
        except Exception as exc:
            raise OrderError("STORAGE_ERROR", f"failed to create order: {exc}") from exc

    def pay_order(self, order_id: str, payment_id: str, amount_cents: int) -> dict[str, Any]:
        _validate_order_id(order_id)
        _validate_payment_id(payment_id)
        if not _is_nonneg_int(amount_cents):
            raise OrderError(
                "INVALID_INPUT",
                "amount_cents must be a non-negative integer",
                {"field": "amount_cents"},
            )

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            row = self._conn.execute(
                "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
                "FROM orders WHERE order_id=?",
                (order_id,),
            ).fetchone()
            if row is None:
                self._conn.rollback()
                raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})

            current_status = row["status"]
            current_payment_id = row["payment_id"]
            total = row["total_cents"]

            # Idempotency: same (order_id, payment_id, amount) returns unchanged
            if current_payment_id == payment_id and current_status in ("paid", "shipped", "cancelled"):
                self._conn.rollback()
                return self._order_to_dict(order_id)

            # Conflict checks
            if current_payment_id is not None and current_payment_id != payment_id:
                self._conn.rollback()
                raise OrderError(
                    "PAYMENT_CONFLICT",
                    "payment_id conflict: order already has a different payment_id",
                    {"order_id": order_id},
                )
            # Check if this payment_id is used by another order
            other = self._conn.execute(
                "SELECT order_id FROM orders WHERE payment_id=? AND order_id!=?",
                (payment_id, order_id),
            ).fetchone()
            if other is not None:
                self._conn.rollback()
                raise OrderError(
                    "PAYMENT_CONFLICT",
                    f"payment_id {payment_id} is already used by another order",
                    {"payment_id": payment_id},
                )

            if amount_cents != total:
                self._conn.rollback()
                raise OrderError(
                    "AMOUNT_MISMATCH",
                    f"amount mismatch: expected {total}, got {amount_cents}",
                    {"expected": total, "actual": amount_cents},
                )

            if current_status != "pending":
                self._conn.rollback()
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot pay order in state {current_status}",
                    {"status": current_status},
                )

            now = self._get_clock()
            self._conn.execute(
                "UPDATE orders SET status='paid', payment_id=?, updated_at=? WHERE order_id=?",
                (payment_id, now, order_id),
            )
            self._conn.commit()
        except OrderError:
            raise
        except Exception as exc:
            raise OrderError("STORAGE_ERROR", f"failed to pay order: {exc}") from exc

        return self._order_to_dict(order_id)

    def cancel_order(self, order_id: str) -> dict[str, Any]:
        _validate_order_id(order_id)

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            row = self._conn.execute(
                "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
                "FROM orders WHERE order_id=?",
                (order_id,),
            ).fetchone()
            if row is None:
                self._conn.rollback()
                raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})

            current_status = row["status"]
            if current_status == "cancelled":
                self._conn.rollback()
                return self._order_to_dict(order_id)
            if current_status == "shipped":
                self._conn.rollback()
                raise OrderError(
                    "INVALID_STATE",
                    "cannot cancel a shipped order",
                    {"status": current_status},
                )
            if current_status not in ("pending", "paid"):
                self._conn.rollback()
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot cancel order in state {current_status}",
                    {"status": current_status},
                )

            # Release stock
            items = self._get_items_for_order(order_id)
            for item in items:
                self._conn.execute(
                    "UPDATE stock SET available = available + ? WHERE sku=?",
                    (item["quantity"], item["sku"]),
                )

            now = self._get_clock()
            self._conn.execute(
                "UPDATE orders SET status='cancelled', updated_at=? WHERE order_id=?",
                (now, order_id),
            )
            self._conn.commit()
        except OrderError:
            raise
        except Exception as exc:
            raise OrderError("STORAGE_ERROR", f"failed to cancel order: {exc}") from exc

        return self._order_to_dict(order_id)

    def ship_order(self, order_id: str) -> dict[str, Any]:
        _validate_order_id(order_id)

        try:
            self._conn.execute("BEGIN IMMEDIATE")
            row = self._conn.execute(
                "SELECT order_id, idempotency_key, status, total_cents, payment_id, created_at, updated_at "
                "FROM orders WHERE order_id=?",
                (order_id,),
            ).fetchone()
            if row is None:
                self._conn.rollback()
                raise OrderError("NOT_FOUND", f"order not found: {order_id}", {"order_id": order_id})

            current_status = row["status"]
            if current_status == "shipped":
                self._conn.rollback()
                return self._order_to_dict(order_id)
            if current_status != "paid":
                self._conn.rollback()
                raise OrderError(
                    "INVALID_STATE",
                    f"cannot ship order in state {current_status}",
                    {"status": current_status},
                )

            now = self._get_clock()
            self._conn.execute(
                "UPDATE orders SET status='shipped', updated_at=? WHERE order_id=?",
                (now, order_id),
            )
            self._conn.commit()
        except OrderError:
            raise
        except Exception as exc:
            raise OrderError("STORAGE_ERROR", f"failed to ship order: {exc}") from exc

        return self._order_to_dict(order_id)

    def get_order(self, order_id: str) -> dict[str, Any]:
        _validate_order_id(order_id)
        try:
            return self._order_to_dict(order_id)
        except OrderError:
            raise
        except Exception as exc:
            raise OrderError("STORAGE_ERROR", f"failed to get order: {exc}") from exc


__all__ = ["OrderError", "OrderService"]

