"""Order fulfillment JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time
import uuid

from . import OrderError, OrderService


def _success(result) -> dict:
    return {"ok": True, "result": result}


def _error(exc: OrderError) -> dict:
    return {"ok": False, "error": {"code": exc.code, "message": exc.message, "details": exc.details}}


def _emit(payload: dict, exit_code: int) -> None:
    sys.stdout.write(json.dumps(payload, sort_keys=True, separators=(",", ":"), allow_nan=False, ensure_ascii=False) + "\n")
    sys.stdout.flush()
    sys.exit(exit_code)


def main() -> None:
    args = sys.argv[1:]
    if len(args) < 2:
        _emit(_error(OrderError("INVALID_INPUT", "usage: python -m src.order_fulfillment --db <path> <command>")), 2)

    if args[0] != "--db":
        _emit(_error(OrderError("INVALID_INPUT", "first argument must be --db")), 2)

    db_path = args[1]
    command = args[2] if len(args) > 2 else ""

    try:
        service = OrderService(db_path, clock=time.time, id_factory=lambda: uuid.uuid4().hex)
    except OrderError as exc:
        _emit(_error(exc), 2)
    except Exception as exc:
        _emit(_error(OrderError("STORAGE_ERROR", f"failed to open service: {exc}")), 3)

    # Read one line of JSON from stdin
    try:
        line = sys.stdin.readline()
    except Exception as exc:
        _emit(_error(OrderError("INVALID_INPUT", f"failed to read stdin: {exc}")), 2)

    if not line:
        input_obj: dict = {}
    else:
        line = line.strip()
        if not line:
            input_obj = {}
        else:
            try:
                input_obj = json.loads(line)
            except json.JSONDecodeError as exc:
                _emit(_error(OrderError("INVALID_INPUT", f"invalid JSON input: {exc}")), 2)
            if not isinstance(input_obj, dict):
                _emit(_error(OrderError("INVALID_INPUT", "input must be a JSON object")), 2)

    try:
        if command == "stock":
            sku = input_obj.get("sku")
            quantity = input_obj.get("quantity")
            extra = set(input_obj.keys()) - {"sku", "quantity"}
            if extra:
                _emit(_error(OrderError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = service.set_stock(sku, quantity)
            _emit(_success(result), 0)

        elif command == "create":
            idempotency_key = input_obj.get("idempotency_key")
            items = input_obj.get("items")
            extra = set(input_obj.keys()) - {"idempotency_key", "items"}
            if extra:
                _emit(_error(OrderError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = service.create_order(idempotency_key, items)
            _emit(_success(result), 0)

        elif command == "pay":
            order_id = input_obj.get("order_id")
            payment_id = input_obj.get("payment_id")
            amount_cents = input_obj.get("amount_cents")
            extra = set(input_obj.keys()) - {"order_id", "payment_id", "amount_cents"}
            if extra:
                _emit(_error(OrderError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = service.pay_order(order_id, payment_id, amount_cents)
            _emit(_success(result), 0)

        elif command == "cancel":
            order_id = input_obj.get("order_id")
            extra = set(input_obj.keys()) - {"order_id"}
            if extra:
                _emit(_error(OrderError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = service.cancel_order(order_id)
            _emit(_success(result), 0)

        elif command == "ship":
            order_id = input_obj.get("order_id")
            extra = set(input_obj.keys()) - {"order_id"}
            if extra:
                _emit(_error(OrderError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = service.ship_order(order_id)
            _emit(_success(result), 0)

        elif command == "get":
            order_id = input_obj.get("order_id")
            extra = set(input_obj.keys()) - {"order_id"}
            if extra:
                _emit(_error(OrderError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = service.get_order(order_id)
            _emit(_success(result), 0)

        else:
            _emit(_error(OrderError("INVALID_INPUT", f"unknown command: {command}")), 2)

    except OrderError as exc:
        code = 2 if exc.code in (
            "INVALID_INPUT", "INVALID_DEPENDENCY", "NOT_FOUND", "INSUFFICIENT_STOCK",
            "IDEMPOTENCY_CONFLICT", "PAYMENT_CONFLICT", "AMOUNT_MISMATCH", "INVALID_STATE",
            "ID_COLLISION", "SCHEMA_MISMATCH",
        ) else 3
        _emit(_error(exc), code)
    except Exception as exc:
        _emit(_error(OrderError("STORAGE_ERROR", f"unexpected error: {exc}")), 3)


if __name__ == "__main__":
    main()

