"""Delivery spool candidate API."""

from __future__ import annotations

import dataclasses
import json
import math
import os
import secrets
import sys
import time
from typing import Any, Callable

SCHEMA_VERSION = 1
STATE_FILENAME = "state.json"
LOCK_FILENAME = "state.lock"


@dataclasses.dataclass(frozen=True)
class Limits:
    max_messages: int = 10000
    max_payload_bytes: int = 65536
    max_attempts: int = 5
    lease_seconds: float = 30.0
    retry_delay: float = 10.0


SPOOL_ERROR_CODES = frozenset(
    {
        "INVALID_INPUT",
        "INVALID_DEPENDENCY",
        "NOT_INITIALIZED",
        "ALREADY_INITIALIZED",
        "NOT_FOUND",
        "IDEMPOTENCY_CONFLICT",
        "CAPACITY_EXCEEDED",
        "UNAUTHORIZED",
        "INVALID_STATE",
        "CORRUPT_STATE",
        "SCHEMA_MISMATCH",
        "LOCK_TIMEOUT",
        "INTERNAL_ERROR",
    }
)


class SpoolError(Exception):
    """Stable spool-domain error."""

    def __init__(self, code: str, message: str, details: dict[str, object] | None = None):
        super().__init__(message)
        self.code: str = code
        self.message: str = message
        self.details: dict[str, object] = details if details is not None else {}

    def __str__(self) -> str:
        return self.message

    def __repr__(self) -> str:
        return f"SpoolError({self.code!r}, {self.message!r})"

    def to_envelope(self) -> dict[str, Any]:
        return {"code": self.code, "message": self.message, "details": self.details}


def _is_nonempty_str(value: Any) -> bool:
    return isinstance(value, str) and value != "" and not value.isspace()


def _is_pos_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool) and value > 0


def _is_nonneg_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and value >= 0


def _is_finite_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _validate_limits(limits: Any) -> Limits:
    if not isinstance(limits, Limits):
        raise SpoolError("INVALID_INPUT", "limits must be a Limits instance", {"field": "limits"})
    for field in ("max_messages", "max_payload_bytes", "max_attempts"):
        value = getattr(limits, field)
        if not _is_pos_int(value):
            raise SpoolError(
                "INVALID_INPUT",
                f"Limits.{field} must be a positive integer",
                {"field": field},
            )
    for field in ("lease_seconds", "retry_delay"):
        value = getattr(limits, field)
        if not _is_nonneg_number(value):
            raise SpoolError(
                "INVALID_INPUT",
                f"Limits.{field} must be a non-negative number",
                {"field": field},
            )
    if limits.lease_seconds <= 0:
        raise SpoolError(
            "INVALID_INPUT",
            "Limits.lease_seconds must be > 0",
            {"field": "lease_seconds"},
        )
    return limits


def _validate_root(root: Any) -> str:
    if not isinstance(root, str) or root == "":
        raise SpoolError("INVALID_INPUT", "root must be a non-empty string", {"field": "root"})
    return root


def _validate_message_id(message_id: Any) -> None:
    if not _is_nonempty_str(message_id):
        raise SpoolError(
            "INVALID_INPUT",
            "message_id must be a non-empty non-whitespace string",
            {"field": "message_id"},
        )


def _validate_worker_id(worker_id: Any) -> None:
    if not _is_nonempty_str(worker_id):
        raise SpoolError(
            "INVALID_INPUT",
            "worker_id must be a non-empty non-whitespace string",
            {"field": "worker_id"},
        )


def _validate_payload(payload: Any, max_bytes: int) -> tuple[Any, int]:
    try:
        encoded = json.dumps(payload, allow_nan=False, ensure_ascii=False, separators=(",", ":"))
    except (TypeError, ValueError, OverflowError) as exc:
        raise SpoolError(
            "INVALID_INPUT",
            f"payload is not JSON-serializable: {exc}",
            {"field": "payload"},
        ) from exc
    byte_len = len(encoded.encode("utf-8"))
    if byte_len > max_bytes:
        raise SpoolError(
            "INVALID_INPUT",
            f"payload exceeds max_payload_bytes ({byte_len} > {max_bytes})",
            {"field": "payload", "size": byte_len, "limit": max_bytes},
        )
    return payload, byte_len


def _canonical_payload(payload: Any) -> str:
    return json.dumps(payload, allow_nan=False, ensure_ascii=False, separators=(",", ":"), sort_keys=True)


def _validate_state(data: Any) -> dict[str, Any]:
    if not isinstance(data, dict):
        raise SpoolError("CORRUPT_STATE", "state must be a JSON object")
    keys = set(data.keys())
    required = {"schema_version", "next_sequence", "messages"}
    if keys != required:
        extra = keys - required
        missing = required - keys
        detail: dict[str, Any] = {}
        if extra:
            detail["extra_fields"] = sorted(extra)
        if missing:
            detail["missing_fields"] = sorted(missing)
        raise SpoolError("CORRUPT_STATE", "state has wrong top-level fields", detail)

    sv = data["schema_version"]
    if not isinstance(sv, int) or isinstance(sv, bool) or sv != SCHEMA_VERSION:
        raise SpoolError("SCHEMA_MISMATCH", f"unsupported schema_version: {sv!r}")

    ns = data["next_sequence"]
    if not isinstance(ns, int) or isinstance(ns, bool) or ns < 1:
        raise SpoolError("CORRUPT_STATE", "next_sequence must be a positive integer", {"next_sequence": ns})

    messages = data["messages"]
    if not isinstance(messages, dict):
        raise SpoolError("CORRUPT_STATE", "messages must be an object")

    valid_statuses = {"pending", "leased", "acked", "dead"}
    for mid, msg in messages.items():
        if not isinstance(msg, dict):
            raise SpoolError("CORRUPT_STATE", f"message {mid!r} must be an object")
        msg_keys = set(msg.keys())
        required_msg = {"message_id", "payload", "status", "available_at", "sequence", "attempts", "last_error"}
        if not required_msg <= msg_keys:
            missing = required_msg - msg_keys
            raise SpoolError("CORRUPT_STATE", f"message {mid!r} missing fields: {sorted(missing)}")
        extra_msg = msg_keys - required_msg - {"lease_token", "worker_id", "expires_at"}
        if extra_msg:
            raise SpoolError("CORRUPT_STATE", f"message {mid!r} has unknown fields: {sorted(extra_msg)}")
        if msg["message_id"] != mid:
            raise SpoolError("CORRUPT_STATE", f"message {mid!r} has mismatched message_id")
        if msg["status"] not in valid_statuses:
            raise SpoolError("CORRUPT_STATE", f"message {mid!r} has invalid status: {msg['status']!r}")
        if not isinstance(msg["attempts"], int) or isinstance(msg["attempts"], bool) or msg["attempts"] < 0:
            raise SpoolError("CORRUPT_STATE", f"message {mid!r} has invalid attempts")
        if msg["status"] == "leased":
            for f in ("lease_token", "worker_id", "expires_at"):
                if f not in msg:
                    raise SpoolError("CORRUPT_STATE", f"leased message {mid!r} missing {f}")
    return data


def _load_state(state_path: str) -> dict[str, Any]:
    try:
        with open(state_path, "r", encoding="utf-8") as f:
            content = f.read()
    except FileNotFoundError:
        raise SpoolError("NOT_INITIALIZED", "state.json not found", {"path": state_path})
    except Exception as exc:
        raise SpoolError("CORRUPT_STATE", f"failed to read state: {exc}") from exc
    # Detect duplicate keys via object_pairs_hook
    def reject_duplicates(pairs):
        seen = set()
        for k, v in pairs:
            if k in seen:
                raise ValueError(f"duplicate key: {k!r}")
            seen.add(k)
        return dict(pairs)
    try:
        data = json.loads(content, object_pairs_hook=reject_duplicates)
    except (json.JSONDecodeError, ValueError) as exc:
        raise SpoolError("CORRUPT_STATE", f"malformed state JSON: {exc}") from exc
    return _validate_state(data)


def _message_to_public(msg: dict[str, Any]) -> dict[str, Any]:
    return {
        "message_id": msg["message_id"],
        "payload": msg["payload"],
        "status": msg["status"],
        "available_at": msg["available_at"],
        "sequence": msg["sequence"],
        "attempts": msg["attempts"],
        "last_error": msg["last_error"],
    }


# Cross-platform file locking
if sys.platform == "win32":
    import msvcrt

    class _Lock:
        def __init__(self, lock_path: str, timeout: float, clock: Callable[[], float]):
            self._lock_path = lock_path
            self._timeout = timeout
            self._clock = clock
            self._fd: int | None = None

        def acquire(self) -> None:
            fd = os.open(self._lock_path, os.O_RDWR | os.O_CREAT, 0o666)
            self._fd = fd
            deadline = self._clock() + self._timeout
            while True:
                try:
                    msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
                    return
                except OSError:
                    if self._clock() >= deadline:
                        os.close(fd)
                        self._fd = None
                        raise SpoolError(
                            "LOCK_TIMEOUT",
                            f"failed to acquire lock within {self._timeout}s",
                            {"lock_path": self._lock_path},
                        )
                    try:
                        time.sleep(0.001)
                    except Exception:
                        pass

        def release(self) -> None:
            if self._fd is not None:
                try:
                    msvcrt.locking(self._fd, msvcrt.LK_UNLCK, 1)
                except Exception:
                    pass
                try:
                    os.close(self._fd)
                except Exception:
                    pass
                self._fd = None

else:
    import fcntl

    class _Lock:
        def __init__(self, lock_path: str, timeout: float, clock: Callable[[], float]):
            self._lock_path = lock_path
            self._timeout = timeout
            self._clock = clock
            self._fd: int | None = None

        def acquire(self) -> None:
            fd = os.open(self._lock_path, os.O_RDWR | os.O_CREAT, 0o666)
            self._fd = fd
            deadline = self._clock() + self._timeout
            while True:
                try:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                    return
                except (IOError, OSError):
                    if self._clock() >= deadline:
                        os.close(fd)
                        self._fd = None
                        raise SpoolError(
                            "LOCK_TIMEOUT",
                            f"failed to acquire lock within {self._timeout}s",
                            {"lock_path": self._lock_path},
                        )
                    try:
                        time.sleep(0.001)
                    except Exception:
                        pass

        def release(self) -> None:
            if self._fd is not None:
                try:
                    fcntl.flock(self._fd, fcntl.LOCK_UN)
                except Exception:
                    pass
                try:
                    os.close(self._fd)
                except Exception:
                    pass
                self._fd = None


class Spool:
    """Filesystem-backed lease spool."""

    def __init__(
        self,
        root: str,
        *,
        clock: Callable[[], float],
        limits: Limits,
        lock_timeout: float,
        failpoint: Callable[[str], None] | None,
    ):
        if not callable(clock):
            raise SpoolError("INVALID_INPUT", "clock must be callable", {"field": "clock"})
        self._root = _validate_root(root)
        self._clock = clock
        self._limits = _validate_limits(limits)
        if not _is_nonneg_number(lock_timeout):
            raise SpoolError("INVALID_INPUT", "lock_timeout must be a non-negative number", {"field": "lock_timeout"})
        self._lock_timeout = float(lock_timeout)
        self._failpoint = failpoint
        self._initialized = os.path.isfile(os.path.join(self._root, STATE_FILENAME))

    def _state_path(self) -> str:
        return os.path.join(self._root, STATE_FILENAME)

    def _temp_path(self) -> str:
        unique = secrets.token_hex(8)
        return os.path.join(self._root, f".state.{os.getpid()}.{unique}.tmp")

    def _lock(self) -> _Lock:
        return _Lock(os.path.join(self._root, LOCK_FILENAME), self._lock_timeout, self._clock)

    def _get_clock(self) -> float:
        try:
            value = self._clock()
        except Exception as exc:
            raise SpoolError("INVALID_DEPENDENCY", f"clock dependency failure: {exc}") from exc
        if not _is_finite_number(value):
            raise SpoolError("INVALID_DEPENDENCY", "clock must return a finite number")
        return float(value)

    def _failpoint_call(self, name: str) -> None:
        if self._failpoint is not None:
            try:
                self._failpoint(name)
            except BaseException:
                raise

    def _read_state_locked(self, lock: _Lock) -> dict[str, Any]:
        # Lock already acquired
        self._failpoint_call("after_lock")
        return _load_state(self._state_path())

    def _write_state_locked(self, state: dict[str, Any], lock: _Lock) -> None:
        # Write to temp file, fsync, then replace
        temp_path = self._temp_path()
        try:
            encoded = json.dumps(state, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False) + "\n"
            with open(temp_path, "w", encoding="utf-8") as f:
                f.write(encoded)
                f.flush()
                os.fsync(f.fileno())
            self._failpoint_call("before_replace")
            os.replace(temp_path, self._state_path())
            # Fsync the directory on supported platforms
            try:
                dir_fd = os.open(self._root, os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except (OSError, NotImplementedError):
                pass
            self._failpoint_call("after_replace")
        finally:
            # Clean up temp file if it still exists
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except Exception:
                pass

    def initialize(self) -> dict[str, Any]:
        os.makedirs(self._root, exist_ok=True)
        state_path = self._state_path()
        lock = self._lock()
        temp_path: str | None = None
        try:
            lock.acquire()
            if os.path.exists(state_path):
                raise SpoolError("ALREADY_INITIALIZED", "spool already initialized", {"root": self._root})
            self._failpoint_call("after_lock")
            state = {"schema_version": SCHEMA_VERSION, "next_sequence": 1, "messages": {}}
            encoded = json.dumps(state, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False) + "\n"
            temp_path = self._temp_path()
            with open(temp_path, "w", encoding="utf-8") as f:
                f.write(encoded)
                f.flush()
                os.fsync(f.fileno())
            self._failpoint_call("before_replace")
            os.replace(temp_path, state_path)
            temp_path = None
            try:
                dir_fd = os.open(self._root, os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except (OSError, NotImplementedError):
                pass
            self._failpoint_call("after_replace")
            self._initialized = True
            return {"schema_version": SCHEMA_VERSION, "next_sequence": 1, "messages": {}}
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to initialize: {exc}") from exc
        finally:
            if temp_path is not None and os.path.exists(temp_path):
                try:
                    os.remove(temp_path)
                except Exception:
                    pass
            lock.release()

    def enqueue(self, message_id: str, payload: Any, available_at: float | None = None) -> dict[str, Any]:
        _validate_message_id(message_id)
        if not isinstance(payload, (type(None), bool, int, float, str, list, dict)):
            raise SpoolError("INVALID_INPUT", "payload must be a JSON-compatible type", {"field": "payload"})
        if available_at is None:
            available_at = self._get_clock()
        elif not _is_finite_number(available_at):
            raise SpoolError("INVALID_INPUT", "available_at must be a finite number", {"field": "available_at"})
        available_at = float(available_at)
        # Validate payload size
        _validate_payload(payload, self._limits.max_payload_bytes)

        lock = self._lock()
        try:
            lock.acquire()
            state = self._read_state_locked(lock)
            messages = state["messages"]
            if message_id in messages:
                existing = messages[message_id]
                if existing["payload"] == payload and float(existing["available_at"]) == available_at:
                    return _message_to_public(existing)
                else:
                    raise SpoolError(
                        "IDEMPOTENCY_CONFLICT",
                        f"message_id {message_id} already exists with different payload or available_at",
                        {"message_id": message_id},
                    )
            if len(messages) >= self._limits.max_messages:
                raise SpoolError(
                    "CAPACITY_EXCEEDED",
                    f"max_messages limit reached: {self._limits.max_messages}",
                    {"limit": self._limits.max_messages},
                )
            sequence = state["next_sequence"]
            msg = {
                "message_id": message_id,
                "payload": payload,
                "status": "pending",
                "available_at": available_at,
                "sequence": sequence,
                "attempts": 0,
                "last_error": None,
            }
            messages[message_id] = msg
            state["next_sequence"] = sequence + 1
            self._write_state_locked(state, lock)
            return _message_to_public(msg)
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to enqueue: {exc}") from exc
        finally:
            lock.release()

    def claim(self, worker_id: str) -> dict[str, Any] | None:
        if not _is_nonempty_str(worker_id):
            raise SpoolError(
                "INVALID_INPUT",
                "worker_id must be a non-empty non-whitespace string",
                {"field": "worker_id"},
            )
        now = self._get_clock()

        lock = self._lock()
        try:
            lock.acquire()
            state = self._read_state_locked(lock)
            messages = state["messages"]
            # Find eligible pending messages
            candidates: list[tuple[float, int, str, dict[str, Any]]] = []
            for mid, msg in messages.items():
                if msg["status"] == "pending" and float(msg["available_at"]) <= now:
                    candidates.append((float(msg["available_at"]), msg["sequence"], mid, msg))
            if not candidates:
                return None
            candidates.sort(key=lambda x: (x[0], x[1], x[2]))
            chosen = candidates[0][3]
            # Lease token: unpredictable, stdlib-generated
            lease_token = secrets.token_hex(32)
            expires_at = now + self._limits.lease_seconds
            chosen["status"] = "leased"
            chosen["attempts"] = chosen["attempts"] + 1
            chosen["lease_token"] = lease_token
            chosen["worker_id"] = worker_id
            chosen["expires_at"] = expires_at
            self._write_state_locked(state, lock)
            result = _message_to_public(chosen)
            result["lease_token"] = lease_token
            return result
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to claim: {exc}") from exc
        finally:
            lock.release()

    def ack(self, message_id: str, lease_token: str) -> dict[str, Any]:
        _validate_message_id(message_id)
        if not _is_nonempty_str(lease_token):
            raise SpoolError(
                "INVALID_INPUT",
                "lease_token must be a non-empty non-whitespace string",
                {"field": "lease_token"},
            )
        lock = self._lock()
        try:
            lock.acquire()
            state = self._read_state_locked(lock)
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", f"message not found: {message_id}", {"message_id": message_id})
            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    f"cannot ack message in state {msg['status']!r}",
                    {"status": msg["status"]},
                )
            expected_token = msg.get("lease_token", "")
            if not secrets.compare_digest(str(expected_token), lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "invalid lease token",
                    {"message_id": message_id},
                )
            msg["status"] = "acked"
            # Clear private lease fields
            for f in ("lease_token", "worker_id", "expires_at"):
                if f in msg:
                    del msg[f]
            self._write_state_locked(state, lock)
            return _message_to_public(msg)
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to ack: {exc}") from exc
        finally:
            lock.release()

    def fail(self, message_id: str, lease_token: str, error: str) -> dict[str, Any]:
        _validate_message_id(message_id)
        if not _is_nonempty_str(lease_token):
            raise SpoolError(
                "INVALID_INPUT",
                "lease_token must be a non-empty non-whitespace string",
                {"field": "lease_token"},
            )
        if not _is_nonempty_str(error):
            raise SpoolError(
                "INVALID_INPUT",
                "error must be a non-empty non-whitespace string",
                {"field": "error"},
            )
        lock = self._lock()
        try:
            lock.acquire()
            state = self._read_state_locked(lock)
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", f"message not found: {message_id}", {"message_id": message_id})
            msg = messages[message_id]
            if msg["status"] != "leased":
                raise SpoolError(
                    "INVALID_STATE",
                    f"cannot fail message in state {msg['status']!r}",
                    {"status": msg["status"]},
                )
            expected_token = msg.get("lease_token", "")
            if not secrets.compare_digest(str(expected_token), lease_token):
                raise SpoolError(
                    "UNAUTHORIZED",
                    "invalid lease token",
                    {"message_id": message_id},
                )
            # Authorized - mutate
            now = self._get_clock()
            msg["last_error"] = error
            for f in ("lease_token", "worker_id", "expires_at"):
                if f in msg:
                    del msg[f]
            if msg["attempts"] >= self._limits.max_attempts:
                msg["status"] = "dead"
            else:
                msg["status"] = "pending"
                msg["available_at"] = now + self._limits.retry_delay
            self._write_state_locked(state, lock)
            return _message_to_public(msg)
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to fail message: {exc}") from exc
        finally:
            lock.release()

    def recover(self) -> dict[str, Any]:
        now = self._get_clock()
        lock = self._lock()
        recovered = 0
        try:
            lock.acquire()
            state = self._read_state_locked(lock)
            messages = state["messages"]
            for mid, msg in messages.items():
                if msg["status"] == "leased" and float(msg.get("expires_at", 0)) <= now:
                    # Clear private lease fields
                    for f in ("lease_token", "worker_id", "expires_at"):
                        if f in msg:
                            del msg[f]
                    if msg["attempts"] >= self._limits.max_attempts:
                        msg["status"] = "dead"
                    else:
                        msg["status"] = "pending"
                        msg["available_at"] = now
                    recovered += 1
            if recovered > 0:
                self._write_state_locked(state, lock)
            return {"recovered": recovered}
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to recover: {exc}") from exc
        finally:
            lock.release()

    def get(self, message_id: str) -> dict[str, Any]:
        _validate_message_id(message_id)
        lock = self._lock()
        try:
            lock.acquire()
            state = self._read_state_locked(lock)
            messages = state["messages"]
            if message_id not in messages:
                raise SpoolError("NOT_FOUND", f"message not found: {message_id}", {"message_id": message_id})
            return _message_to_public(messages[message_id])
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to get: {exc}") from exc
        finally:
            lock.release()

    def list_messages(self, status: str | None = None) -> list[dict[str, Any]]:
        if status is not None:
            valid_statuses = {"pending", "leased", "acked", "dead"}
            if not isinstance(status, str) or status not in valid_statuses:
                raise SpoolError(
                    "INVALID_INPUT",
                    f"invalid status filter: {status!r}",
                    {"field": "status"},
                )
        lock = self._lock()
        try:
            lock.acquire()
            state = self._read_state_locked(lock)
            messages = state["messages"]
            result = []
            for mid, msg in messages.items():
                if status is None or msg["status"] == status:
                    entry = _message_to_public(msg)
                    entry["_sort_key"] = (float(msg["available_at"]), msg["sequence"], msg["message_id"])
                    result.append(entry)
            result.sort(key=lambda x: x["_sort_key"])
            for r in result:
                del r["_sort_key"]
            return result
        except SpoolError:
            raise
        except Exception as exc:
            raise SpoolError("INTERNAL_ERROR", f"failed to list: {exc}") from exc
        finally:
            lock.release()


