"""Delivery spool JSON CLI entry point."""

from __future__ import annotations

import json
import sys
import time

from . import Limits, Spool, SpoolError


def _success(result) -> dict:
    return {"ok": True, "result": result}


def _error(exc: SpoolError) -> dict:
    return {"ok": False, "error": {"code": exc.code, "message": exc.message, "details": exc.details}}


def _emit(payload: dict, exit_code: int) -> None:
    sys.stdout.write(json.dumps(payload, sort_keys=True, separators=(",", ":"), allow_nan=False, ensure_ascii=False) + "\n")
    sys.stdout.flush()
    sys.exit(exit_code)


def _parse_input(args: list[str], command: str) -> dict:
    # Commands that may omit input
    if command in ("init", "recover", "list") and len(args) == 0:
        return {}
    line = sys.stdin.readline()
    if not line:
        return {}
    line = line.strip()
    if not line:
        return {}
    try:
        obj = json.loads(line)
    except json.JSONDecodeError as exc:
        raise SpoolError("INVALID_INPUT", f"invalid JSON input: {exc}") from exc
    if not isinstance(obj, dict):
        raise SpoolError("INVALID_INPUT", "input must be a JSON object")
    return obj


def main() -> None:
    args = sys.argv[1:]
    if len(args) < 2:
        _emit(_error(SpoolError("INVALID_INPUT", "usage: python -m src.delivery_spool --root <path> <command>")), 2)

    if args[0] != "--root":
        _emit(_error(SpoolError("INVALID_INPUT", "first argument must be --root")), 2)

    root = args[1]
    command = args[2] if len(args) > 2 else ""

    try:
        spool = Spool(root, clock=time.time, limits=Limits(), lock_timeout=10.0, failpoint=None)
    except SpoolError as exc:
        _emit(_error(exc), 2)
    except Exception as exc:
        _emit(_error(SpoolError("INTERNAL_ERROR", f"failed to open spool: {exc}")), 3)

    try:
        input_obj = _parse_input(args[3:], command)
    except SpoolError as exc:
        _emit(_error(exc), 2)

    try:
        if command == "init":
            extra = set(input_obj.keys())
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.initialize()
            _emit(_success(result), 0)

        elif command == "enqueue":
            message_id = input_obj.get("message_id")
            payload = input_obj.get("payload")
            available_at = input_obj.get("available_at", None)
            extra = set(input_obj.keys()) - {"message_id", "payload", "available_at"}
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.enqueue(message_id, payload, available_at)
            _emit(_success(result), 0)

        elif command == "claim":
            worker_id = input_obj.get("worker_id")
            extra = set(input_obj.keys()) - {"worker_id"}
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.claim(worker_id)
            _emit(_success(result), 0)

        elif command == "ack":
            message_id = input_obj.get("message_id")
            lease_token = input_obj.get("lease_token")
            extra = set(input_obj.keys()) - {"message_id", "lease_token"}
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.ack(message_id, lease_token)
            _emit(_success(result), 0)

        elif command == "fail":
            message_id = input_obj.get("message_id")
            lease_token = input_obj.get("lease_token")
            error = input_obj.get("error")
            extra = set(input_obj.keys()) - {"message_id", "lease_token", "error"}
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.fail(message_id, lease_token, error)
            _emit(_success(result), 0)

        elif command == "recover":
            extra = set(input_obj.keys())
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.recover()
            _emit(_success(result), 0)

        elif command == "show":
            message_id = input_obj.get("message_id")
            extra = set(input_obj.keys()) - {"message_id"}
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.get(message_id)
            _emit(_success(result), 0)

        elif command == "list":
            status = input_obj.get("status", None)
            extra = set(input_obj.keys()) - {"status"}
            if extra:
                _emit(_error(SpoolError("INVALID_INPUT", f"unknown fields: {sorted(extra)}")), 2)
            result = spool.list_messages(status)
            _emit(_success(result), 0)

        else:
            _emit(_error(SpoolError("INVALID_INPUT", f"unknown command: {command}")), 2)

    except SpoolError as exc:
        code = 2 if exc.code in (
            "INVALID_INPUT", "INVALID_DEPENDENCY", "NOT_INITIALIZED", "ALREADY_INITIALIZED",
            "NOT_FOUND", "IDEMPOTENCY_CONFLICT", "CAPACITY_EXCEEDED", "UNAUTHORIZED",
            "INVALID_STATE", "SCHEMA_MISMATCH",
        ) else 3
        _emit(_error(exc), code)
    except Exception as exc:
        _emit(_error(SpoolError("INTERNAL_ERROR", f"unexpected error: {exc}")), 3)


if __name__ == "__main__":
    main()

